write('brandon-hope.html', page('Brandon & Hope — client website', f'''<section class="page-intro wrap"><a class="back-link" href="chrisWebDev.html">← Back to work</a><p class="eyebrow">CLIENT WEBSITE / WEB DEVELOPMENT</p><h1>A celebration.<br>A shared <span class="serif">destination.</span></h1><p>A wedding website for Brandon & Hope, bringing their story, celebration details, and guest information together.</p><a class="button" href="https://mehnchris.github.io/BrandonANDHope/" target="_blank" rel="noopener noreferrer">Visit live website ↗</a></section><section class="wrap case-visual">{wedding_visual()}</section><section class="wrap section case-body"><aside><p class="eyebrow">PROJECT DETAILS</p><h3>Brandon & Hope</h3><p>Client wedding website</p><p>HTML · CSS<br>Responsive layout<br>Google Forms RSVP</p></aside><div><h2>Everything guests need.<br>One <span class="serif">thoughtful place.</span></h2><p>A wedding website needs to feel personal while keeping practical information easy to find. This project brings together the couple’s story, venue details, schedule, travel guidance, and an RSVP handoff.</p><h3>A clear path through the day</h3><p>The page organizes information into focused sections, helping guests move from the story to the logistics. A warm palette and expressive typography reflect the celebratory character of the event.</p><h3>A practical RSVP approach</h3><p>Prominent RSVP links direct guests to Google Forms, giving the couple a familiar way to manage responses. The public site remains a straightforward, accessible source of event information.</p><h3>Designed for different screens</h3><p>Flexible grids and responsive typography adapt the content for desktop and mobile, including stacked details and full-width actions on smaller screens.</p><a class="text-link" href="https://mehnchris.github.io/BrandonANDHope/" target="_blank" rel="noopener noreferrer">Explore the live project ↗</a></div></section>''', 'Work'))

write('enterprise.html', page('Connected enterprise workflows', f'''<section class="page-intro wrap"><a class="back-link" href="chrisWebDev.html">← Back to work</a><p class="eyebrow">PROFESSIONAL EXPERIENCE / PROGRESSIVE EDGE INC</p><h1>Complex systems.<br><span class="serif">Connected thinking.</span></h1><p>Enterprise application development that connects the work in someone’s hands with the business data behind it.</p></section><section class="wrap case-visual">{system_visual()}</section><section class="wrap section case-body"><aside><p class="eyebrow">ROLE & TECHNOLOGY</p><h3>Project Manager / Programmer</h3><p>October 2025 — present</p><p>C# · .NET MAUI<br>Custom REST middleware<br>SQL Server ERP</p><small>Conceptual workflow illustration.<br>No client data shown.</small></aside><div><h2>From a barcode<br>to a business <span class="serif">workflow.</span></h2><p>At Progressive Edge Inc, my work includes developing an enterprise Android application using .NET MAUI. It integrates barcode scanning, inventory lookup, and label printing with a SQL Server ERP backend.</p><h3>The application and the connection</h3><p>A custom REST middleware layer connects the application to the underlying system. This work brings together mobile development, API design, and data access to support operational tasks.</p><h3>Development starts with listening</h3><p>Alongside programming, I communicate with clients to clarify requirements and troubleshoot issues. Understanding the actual workflow helps connect implementation decisions to the people using the application.</p><a class="text-link" href="resume.html">See my full experience ↗</a></div></section>''', 'Work'))

